draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "middle";

var scale = (H - 60) / 0.9;   // pixels per metre of liquid
var bottomY = H - 26;
var tubeW = Math.min(W * 0.13, 52);
var gapW = Math.min(W * 0.22, 110);
var midX = W * 0.45;
var lx = midX - gapW / 2 - tubeW, rx = midX + gapW / 2;

var hOil = p.hOil;
var rhoOil = p.rhoOil;
var rhoW = 1000;
// water in right arm stands above the interface by rhoOil*hOil/rhoW
var rise = rhoOil * hOil / rhoW;

var interfaceY = bottomY - 0.22 * scale;      // interface in the left arm
var oilTopY = interfaceY - hOil * scale;
var rightY = interfaceY - rise * scale;

// tube outline
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(lx, 20); ctx.lineTo(lx, bottomY); ctx.lineTo(rx + tubeW, bottomY); ctx.lineTo(rx + tubeW, 20);
ctx.moveTo(lx + tubeW, 20); ctx.lineTo(lx + tubeW, bottomY - 16); ctx.lineTo(rx, bottomY - 16); ctx.lineTo(rx, 20);
ctx.stroke();

// water fill
ctx.fillStyle = C.accent;
ctx.globalAlpha = 0.20;
ctx.fillRect(lx + 1, interfaceY, tubeW - 2, bottomY - interfaceY - 1);
ctx.fillRect(rx + 1, rightY, tubeW - 2, bottomY - rightY - 1);
ctx.fillRect(lx + tubeW, bottomY - 16, rx - lx - tubeW, 15);
ctx.globalAlpha = 1;

// oil fill
ctx.fillStyle = C.figure;
ctx.globalAlpha = 0.35;
ctx.fillRect(lx + 1, oilTopY, tubeW - 2, hOil * scale);
ctx.globalAlpha = 1;

// level lines
ctx.strokeStyle = C.ink;
ctx.lineWidth = 1.4;
ctx.beginPath(); ctx.moveTo(lx, interfaceY); ctx.lineTo(lx + tubeW, interfaceY); ctx.stroke();
ctx.beginPath(); ctx.moveTo(lx, oilTopY); ctx.lineTo(lx + tubeW, oilTopY); ctx.stroke();
ctx.beginPath(); ctx.moveTo(rx, rightY); ctx.lineTo(rx + tubeW, rightY); ctx.stroke();

// the matching-level line through the interface
ctx.strokeStyle = C.accent;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(lx, interfaceY); ctx.lineTo(rx + tubeW + 6, interfaceY); ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.accent;
ctx.fillText("same level, same pressure", lx - 4, interfaceY + 14);

ctx.fillStyle = C.figure;
ctx.fillText("oil", lx + tubeW / 2 - 8, (oilTopY + interfaceY) / 2);
ctx.fillStyle = C.ink;
ctx.fillText("water", rx + tubeW + 6, (rightY + bottomY) / 2);

// height annotations
function dim(x, y0, y1, label) {
  ctx.strokeStyle = C.faint;
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(x, y0); ctx.lineTo(x, y1); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(x - 4, y0); ctx.lineTo(x + 4, y0);
  ctx.moveTo(x - 4, y1); ctx.lineTo(x + 4, y1); ctx.stroke();
  ctx.fillStyle = C.faint;
  ctx.fillText(label, x + 6, (y0 + y1) / 2);
}
dim(lx - 16, oilTopY, interfaceY, hOil.toFixed(2) + " m oil");
dim(rx + tubeW + 40, rightY, interfaceY, rise.toFixed(3) + " m");

out.note = "rho_oil h_oil = rho_water h_water, so the water stands " +
  rise.toFixed(3) + " m above the interface";
